 */
public record ReportRequest(
        @NotBlank String requestId,
        String batchId,
        @NotBlank String crewId,
        @NotBlank String flightNo,
        @NotNull OffsetDateTime reportTime,
        @NotNull OffsetDateTime scheduledEndTime) {
}

