/** 查询某批次中某成员的全部值勤记录（按报到时刻升序）。 */
public List<DutyRecord> findDutiesInBatchByCrew(String batchId, String crewId) {
    return jdbcTemplate.query("""
            SELECT d.* FROM batch_duty b
            JOIN duty_record d ON d.request_id = b.request_id
            WHERE b.batch_id = ? AND d.crew_id = ?
            ORDER BY d.report_time ASC
            """, DUTY_MAPPER, batchId, crewId);
}

