25	import java.util.LinkedHashSet;
26	import java.util.List;
27	import java.util.Set;
28	
29	/**
30	 * 值勤合规应用服务：报到、整组校验、延误延长、封板。
31	 *
32	 * <p>所有判定与写入在事务内完成；同一机组成员同日延误累计的读-判-写临界区
33	 * 用进程内 {@link KeyLock} 串行化（嵌入式 H2 仅运行于单 JVM）。
34	 */
35	@Service
36	public class CrewLegalityService {
37	
38	    private final DutyRepository repository;
39	    private final Clock clock;
40	    private final TransactionTemplate transactionTemplate;
41	    private final KeyLock crewLocks = new KeyLock();
42	    private final KeyLock delayLocks = new KeyLock();
43	
44	    public CrewLegalityService(DutyRepository repository,
45	                               Clock clock,
46	                               org.springframework.transaction.PlatformTransactionManager txManager) {
47	        this.repository = repository;
48	        this.clock = clock;
49	        this.transactionTemplate = new TransactionTemplate(txManager);
50	    }
51	
52	    /** 单条值勤报到：requestId 幂等，同键异参 409 且不写入。 */
53	    public ReportResponse report(ReportRequest request) {
54	        // 串行化同一机组成员的并发报到，保证同一时段只受理一条，事务包在锁内。
55	        String crewKey = crewKey(request.crewId());
56	        crewLocks.lock(crewKey);
57	        try {
58	            return transactionTemplate.execute(status -> doReport(request));
59	        } finally {
60	            crewLocks.unlock(crewKey);
61	        }
62	    }
63	
64	    private ReportResponse doReport(ReportRequest request) {
65	        OffsetDateTime reportUtc = utc(request.reportTime());
66	        OffsetDateTime endUtc = utc(request.scheduledEndTime());
67	        if (endUtc.isBefore(reportUtc)) {
68	            throw new BadRequestException("scheduledEndTime must not be before reportTime");
69	        }
70	        String batchId = normalizeBatchId(request.batchId());
71	        ensureBatchOpen(batchId);
72	
73	        // 幂等：同 requestId 同参返回首次判定；同键异参 409 不写入。
74	        DutyRecord existing = repository.findByRequestId(request.requestId());
75	        if (existing != null) {
76	            if (!sameFingerprint(existing, request.crewId(), request.flightNo(), reportUtc)) {
77	                throw new IdempotentConflictException(request.requestId());
78	            }
79	            return toReportResponse(existing, true);
80	        }
81	
82	        List<String> reasons = evaluateMember(request.crewId(), reportUtc, endUtc, 0, request.requestId());
83	        DutyRecord record = new DutyRecord(
84	                request.requestId(), batchId, request.crewId(), request.flightNo(),
85	                reportUtc, endUtc, 0, reasons.isEmpty(), joinReasons(reasons), nowUtc());
86	        try {
87	            repository.insertDuty(record);
88	        } catch (DuplicateKeyException ex) {
89	            // 并发：requestId 唯一键或成员报到时刻唯一键冲突，只接受首条，其余按幂等重放。
90	            DutyRecord winner = repository.findByRequestId(request.requestId());
91	            if (winner == null) {
92	                winner = repository.findBySlot(request.crewId(), reportUtc);
93	            }
94	            if (winner == null) {
95	                throw ex;
96	            }
97	            if (winner.batchId() != null && !winner.batchId().equals(batchId)) {
98	                throw new IdempotentConflictException(request.requestId());
99	            }
100	            return toReportResponse(winner, true);
101	        }
102	
103	        if (batchId != null) {
104	            repository.linkDutyToBatch(batchId, request.requestId());
105	            recomputeBatchVerdict(batchId);
106	        }
107	        return toReportResponse(record, false);
108	    }
109	
110	    /** 整组校验：每个成员独立判定，同一事务内给出整组结果；任一成员违规则整组违规。 */
111	    public BatchCheckResponse checkBatch(BatchCheckRequest request) {
112	        for (BatchCheckRequest.MemberDuty member : request.members()) {
113	            if (utc(member.scheduledEndTime()).isBefore(utc(member.reportTime()))) {
114	                throw new BadRequestException(
115	                        "scheduledEndTime must not be before reportTime: " + member.requestId());
116	            }
117	        }
118	        // 有序获取涉及成员锁（与单条报到互斥、避免死锁），整组判定仍在同一事务内完成。
119	        List<String> orderedCrew = request.members().stream()
120	                .map(BatchCheckRequest.MemberDuty::crewId)
121	                .distinct().sorted().toList();
122	        orderedCrew.forEach(crew -> crewLocks.lock(crewKey(crew)));
123	        try {
124	            return transactionTemplate.execute(status -> doCheckBatch(request));
125	        } finally {
126	            for (int i = orderedCrew.size() - 1; i >= 0; i--) {
127	                crewLocks.unlock(crewKey(orderedCrew.get(i)));
128	            }
129	        }
130	    }
131	
132	    private BatchCheckResponse doCheckBatch(BatchCheckRequest request) {
133	        String batchId = request.batchId();
134	
135	        CheckBatch batch = repository.findBatch(batchId);
136	        if (batch != null && batch.status() == BatchStatus.FINALIZED) {
137	            throw new BatchFinalizedException(batchId);
138	        }
139	        if (batch == null) {
140	            repository.insertBatch(new CheckBatch(
141	                    batchId, BatchStatus.CHECKED, true, nowUtc(), null));
142	        }
143	
144	        for (BatchCheckRequest.MemberDuty member : request.members()) {
145	            acceptMemberDuty(batchId, member);
146	        }
147	
148	        boolean groupLegal = recomputeBatchVerdict(batchId);
149	        return buildBatchResponse(batchId, groupLegal, BatchStatus.CHECKED);
150	    }
151	
152	    /**
153	     * 将批次成员条目落库为值勤记录：幂等复用首条记录，同键异参 409，时段并发冲突只受理一条。
154	     */
155	    private void acceptMemberDuty(String batchId, BatchCheckRequest.MemberDuty member) {
156	        OffsetDateTime reportUtc = utc(member.reportTime());
157	        OffsetDateTime endUtc = utc(member.scheduledEndTime());
158	
159	        DutyRecord existing = repository.findByRequestId(member.requestId());
160	        if (existing != null) {
161	            if (!sameFingerprint(existing, member.crewId(), member.flightNo(), reportUtc)) {
162	                throw new IdempotentConflictException(member.requestId());
163	            }
164	            if (existing.batchId() != null && !existing.batchId().equals(batchId)) {
165	                throw new IdempotentConflictException(member.requestId());
166	            }
167	            if (existing.batchId() == null) {
168	                repository.attachBatch(existing.requestId(), batchId);
169	            }
170	            repository.linkDutyToBatch(batchId, existing.requestId());
171	            return;
172	        }
173	
174	        DutyRecord sameSlot = repository.findBySlot(member.crewId(), reportUtc);
175	        if (sameSlot != null) {
176	            if (sameSlot.batchId() != null && !sameSlot.batchId().equals(batchId)) {
177	                throw new IdempotentConflictException(member.requestId());
178	            }
179	            if (sameSlot.batchId() == null) {
180	                repository.attachBatch(sameSlot.requestId(), batchId);
181	            }
182	            repository.linkDutyToBatch(batchId, sameSlot.requestId());
183	            return;
184	        }
185	
186	        List<String> reasons = evaluateMember(member.crewId(), reportUtc, endUtc, 0, member.requestId());
187	        DutyRecord record = new DutyRecord(
188	                member.requestId(), batchId, member.crewId(), member.flightNo(),
189	                reportUtc, endUtc, 0, reasons.isEmpty(), joinReasons(reasons), nowUtc());
190	        try {
191	            repository.insertDuty(record);
192	        } catch (DuplicateKeyException ex) {
193	            DutyRecord winner = repository.findByRequestId(member.requestId());
194	            if (winner == null) {
195	                winner = repository.findBySlot(member.crewId(), reportUtc);
196	            }
197	            if (winner == null) {
198	                throw ex;
199	            }
200	            if (winner.batchId() != null && !winner.batchId().equals(batchId)) {
201	                throw new IdempotentConflictException(member.requestId());
202	            }
203	            repository.linkDutyToBatch(batchId, winner.requestId());
204	            return;
205	        }
206	        repository.linkDutyToBatch(batchId, member.requestId());
207	    }
208	
209	    /**
210	     * 延误延长：封板前应用并重判（同一事务内同步成员与整组结论）；
211	     * 封板后仅登记为迟到事件（applied=0），不推翻终态结论。
212	     */
213	    public DelayResponse submitDelay(DelayRequest request) {
214	        DutyRecord record = repository.findByRequestId(request.requestId());
215	        if (record == null) {
216	            throw new ResourceNotFoundException("duty not found: " + request.requestId());
217	        }
218	        boolean finalized = record.batchId() != null
219	                && repository.findBatch(record.batchId()).status() == BatchStatus.FINALIZED;
220	        LocalDate dutyDay = record.reportTime().toLocalDate();
221	
222	        if (finalized) {
223	            return transactionTemplate.execute(status -> {
224	                repository.insertDelayEvent(request.requestId(), record.crewId(), dutyDay,
225	                        request.delayMinutes(), false, nowUtc());
226	                int appliedTotal = repository.sumAppliedDelayOnDate(
227	                        record.crewId(), dutyDay, "__none__");
228	                return new DelayResponse(request.requestId(), false, appliedTotal,
229	                        record.legal(), splitReasons(record.reasons()), true);
230	            });
231	        }
232	
233	        // 串行化同成员的延误累计与级联重判（可能跨多个 UTC 日历日），事务边界包在锁内。
234	        // 锁序固定 delay -> crew，不存在反向获取，不会死锁。
235	        String delayKey = "delay:" + record.crewId();
236	        String crewKey = crewKey(record.crewId());
237	        delayLocks.lock(delayKey);
238	        crewLocks.lock(crewKey);
239	        try {
240	            return transactionTemplate.execute(status -> {
241	                DutyRecord current = repository.findByRequestId(request.requestId());
242	                int otherDelay = repository.sumAppliedDelayOnDate(
243	                        current.crewId(), dutyDay, current.requestId());
244	                int newTotal = current.delayMinutes() + request.delayMinutes();
245	                List<String> reasons = evaluateMember(
246	                        current.crewId(), current.reportTime(), current.scheduledEndTime(),
247	                        newTotal, current.requestId());
248	                repository.insertDelayEvent(current.requestId(), current.crewId(), dutyDay,
249	                        request.delayMinutes(), true, nowUtc());
250	                repository.updateDutyVerdict(current.requestId(), newTotal,
251	                        reasons.isEmpty(), joinReasons(reasons));
252	
253	                Set<String> affectedBatches = new HashSet<>();
254	                // 较早执勤延长会改变后续执勤的休息期与 7 日窗口：按时间顺序级联重判未封板记录。
255	                for (DutyRecord later : repository.findDutiesAfter(
256	                        current.crewId(), current.reportTime())) {
257	                    if (later.batchId() != null
258	                            && repository.findBatch(later.batchId()).status() == BatchStatus.FINALIZED) {
259	                        continue;
260	                    }
261	                    List<String> laterReasons = evaluateMember(
262	                            later.crewId(), later.reportTime(), later.scheduledEndTime(),
263	                            later.delayMinutes(), later.requestId());
264	                    repository.updateDutyVerdict(later.requestId(), later.delayMinutes(),
265	                            laterReasons.isEmpty(), joinReasons(laterReasons));
266	                    if (later.batchId() != null) {
267	                        affectedBatches.add(later.batchId());
268	                    }
269	                }
270	                // 当前记录及全部级联记录所属批次都重建成员聚合与整组结论。
271	                if (current.batchId() != null) {
272	                    affectedBatches.add(current.batchId());
273	                }
274	                for (String affectedBatch : affectedBatches) {
275	                    recomputeBatchVerdict(affectedBatch);
276	                }
277	                return new DelayResponse(current.requestId(), true, otherDelay + newTotal,
278	                        reasons.isEmpty(), reasons, false);
279	            });
280	        } finally {
281	            crewLocks.unlock(crewKey);
282	            delayLocks.unlock(delayKey);
283	        }
284	    }
285	
286	    /** 封板：结论终态；重复封板返回幂等成功。 */
287	    public FinalizeResponse finalizeBatch(String batchId) {
288	        return transactionTemplate.execute(status -> {
289	            CheckBatch batch = repository.findBatch(batchId);
290	            if (batch == null) {
291	                throw new ResourceNotFoundException("batch not found: " + batchId);
292	            }
293	            if (batch.status() == BatchStatus.FINALIZED) {
294	                return new FinalizeResponse(batchId, batch.legal(), true);
295	            }
296	            boolean groupLegal = recomputeBatchVerdict(batchId);
297	            repository.markFinalized(batchId, groupLegal, nowUtc());
298	            return new FinalizeResponse(batchId, groupLegal, false);
299	        });
300	    }
301	
302	    /** 调用规则引擎评估单个成员：载入其报到时刻之前的历史记录与当日已有延长。 */
303	    private List<String> evaluateMember(String crewId, OffsetDateTime reportUtc,
304	                                        OffsetDateTime endUtc, int delayMinutes,
305	                                        String excludeRequestId) {
306	        List<DutyRecord> history = repository.findHistoryBefore(crewId, reportUtc);
307	        int priorDayDelay = repository.sumAppliedDelayOnDate(
308	                crewId, reportUtc.toLocalDate(), excludeRequestId);
309	        return LegalityRules.evaluate(reportUtc, endUtc, delayMinutes, history, priorDayDelay);
310	    }
311	
312	    /**
313	     * 按批次内全部值勤记录重建成员聚合判定并写入整组结论：
314	     * 成员任一段违规则成员违规，任一成员违规则整组违规。
315	     */
316	    private boolean recomputeBatchVerdict(String batchId) {
317	        List<Object[]> aggregates = repository.aggregateBatchDuties(batchId);
318	        boolean groupLegal = true;
319	        for (Object[] row : aggregates) {
320	            String crewId = (String) row[0];
321	            boolean memberLegal = (Integer) row[1] == 1;
322	            String reasons = normalizeReasons((String) row[2]);
323	            repository.upsertBatchMember(batchId, crewId, memberLegal, reasons);
324	            groupLegal &= memberLegal;
325	        }
326	        repository.updateBatchVerdict(batchId, groupLegal);
327	        return groupLegal;
328	    }
329	
330	    private BatchCheckResponse buildBatchResponse(String batchId, boolean groupLegal, BatchStatus status) {
331	        List<BatchCheckResponse.MemberResult> results = new ArrayList<>();
332	        for (Object[] row : repository.findBatchMembers(batchId)) {
333	            results.add(new BatchCheckResponse.MemberResult(
334	                    (String) row[0], (Integer) row[1] == 1, splitReasons((String) row[2])));
335	        }
336	        return new BatchCheckResponse(batchId, groupLegal, status.name(), results);
337	    }
338	
339	    /** LISTAGG 跨段拼接的原因串可能含重复码，按出现顺序去重后再落库。 */
340	    private String normalizeReasons(String aggregated) {
341	        if (aggregated == null || aggregated.isEmpty()) {
342	            return "";
343	        }
344	        LinkedHashSet<String> unique = new LinkedHashSet<>(splitReasons(aggregated));
345	        return joinReasons(new ArrayList<>(unique));
346	    }
347	
348	    /** 校验批次处于可写入状态：已封板批次的补报/改签一律拒绝，须走新批次。 */
349	    private void ensureBatchOpen(String batchId) {
350	        if (batchId == null) {
351	            return;
352	        }
353	        CheckBatch batch = repository.findBatch(batchId);
354	        if (batch == null) {
355	            repository.insertBatch(new CheckBatch(
356	                    batchId, BatchStatus.CHECKED, true, nowUtc(), null));
357	            return;
358	        }
359	        if (batch.status() == BatchStatus.FINALIZED) {
360	            throw new BatchFinalizedException(batchId);
361	        }
362	    }
363	
364	    private boolean sameFingerprint(DutyRecord record, String crewId, String flightNo,
365	                                    OffsetDateTime reportUtc) {
366	        return record.crewId().equals(crewId)
367	                && record.flightNo().equals(flightNo)
368	                && record.reportTime().toInstant().equals(reportUtc.toInstant());
369	    }
370	
371	    private ReportResponse toReportResponse(DutyRecord record, boolean replayed) {
372	        return new ReportResponse(record.requestId(), record.batchId(), record.crewId(),
373	                record.flightNo(), record.legal(), splitReasons(record.reasons()),
374	                record.delayMinutes(), replayed);
375	    }
376	
377	    private static OffsetDateTime utc(OffsetDateTime time) {
378	        return time.withOffsetSameInstant(ZoneOffset.UTC);
379	    }
380	
381	    private OffsetDateTime nowUtc() {
382	        return OffsetDateTime.now(clock).withOffsetSameInstant(ZoneOffset.UTC);
383	    }
384	
385	    private String normalizeBatchId(String batchId) {
386	        if (batchId == null || batchId.isBlank()) {
387	            return null;
388	        }
389	        return batchId;
390	    }
391	
392	    private String crewKey(String crewId) {
393	        return "crew:" + crewId;
394	    }
395	
396	    static String joinReasons(List<String> reasons) {
397	        return String.join(",", reasons);
398	    }
399	
400	    static List<String> splitReasons(String reasons) {
401	        if (reasons == null || reasons.isEmpty()) {
402	            return List.of();
403	        }
404	        return Arrays.asList(reasons.split(","));
405	    }
406	}
